// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address logger, bool status) public {
        vm.assume(logger != address(0));
        // _contractOwner is never assigned, so it defaults to address(0); that is the only authorized caller.
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);
        assertTrue(c.approvedToLog(logger) == status, "approvedToLog must equal the status set by owner");
    }
}
